'use strict';
let endpoint='', access='', remote=null, timer=null, busy=false;
const localToggle=$('toggle').onclick,localClose=$('close').onclick,localExample=$('example').onclick,localConfig=$('config').onsubmit,localReset=$('reset').onclick,localExport=$('export').onclick,localDraw=draw;
if(['localhost','127.0.0.1'].includes(location.hostname))$('server-url').value=location.origin;
async function api(path,payload){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(endpoint+'/api/'+path,{method:payload?'POST':'GET',headers:{Authorization:'Bearer '+access,...(payload?{'Content-Type':'application/json'}:{})},body:payload?JSON.stringify(payload):undefined,signal:controller.signal});const value=await r.json();if(!r.ok)throw Error(value.error||'Error del servidor');if(value.mode!=='generated-paper'||value.broker_connected!==false)throw Error('Este panel solo acepta el motor de simulación');return value;}finally{clearTimeout(timeout);}}
function remoteDraw(){if(!remote)return localDraw();const c=$('chart'),r=c.getBoundingClientRect();if(!r.width)return;const dpr=window.devicePixelRatio||1,w=r.width,h=340;c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);const prices=remote.prices;if(prices.length<2){x.fillStyle='#9ab4cf';x.fillText('Esperando precios generados…',20,40);return;}const lo=Math.min(...prices)-.0005,hi=Math.max(...prices)+.0005;const y=p=>h-30-(p-lo)/(hi-lo)*(h-60);x.font='11px system-ui';for(let i=0;i<5;i++){const p=lo+(hi-lo)*i/4;x.strokeStyle='#243a4e';x.beginPath();x.moveTo(0,y(p));x.lineTo(w-60,y(p));x.stroke();x.fillStyle='#9ab4cf';x.fillText(p.toFixed(5),w-58,y(p)+4);}x.strokeStyle='#16c8bc';x.lineWidth=2;x.beginPath();prices.forEach((p,i)=>i?x.lineTo(i*(w-70)/(prices.length-1)+5,y(p)):x.moveTo(5,y(p)));x.stroke();x.fillStyle='#9ab4cf';x.fillText('Ticks sintéticos · un paso cada 5 segundos · no representan velas M15',10,h-5);}
function showRemote(){if(!remote)return;$('balance').textContent=money(remote.balance);$('profit').textContent=money(remote.balance-1000);$('risk').textContent=remote.trades.reduce((a,t)=>a+t.risk,0).toFixed(1)+'% / 2%';$('count').textContent=remote.trades.length+' / 2';$('status').textContent=remote.active?'● Motor simulado activo':'● Entradas simuladas pausadas';$('toggle').textContent=remote.active?'Pausar entradas':'Activar motor simulado';$('risk-label').textContent=remote.risk+'%';if(document.activeElement!==$('risk-input'))$('risk-input').value=remote.risk;document.querySelector('.connection').replaceChildren();const span=document.createElement('span');span.textContent='● Motor simulado · Conectado';const small=document.createElement('small');small.textContent='OANDA sin conectar';document.querySelector('.connection').append(span,small);document.querySelector('.chart-head span').textContent='Ticks generados · SMA 5/20';document.querySelector('.chart-head b').textContent=remote.price.toFixed(5);document.querySelector('.controls p').textContent='Cruce de medias sobre precios sintéticos. Estrategia educativa sin validar.';document.querySelector('.chart p').textContent='Equity simulada: '+money(remote.equity)+' · Pérdida diaria: '+remote.loss_percent+'%';$('trades').replaceChildren();for(const t of remote.trades)row($('trades'),['EUR/USD',t.direction===1?'Compra':'Venta',t.units,t.entry.toFixed(5),t.stop.toFixed(5),t.target.toFixed(5),money(t.profit)]);if(!remote.trades.length)row($('trades'),['Sin posiciones simuladas abiertas.']);$('history').replaceChildren();for(const t of remote.history)row($('history'),[t.time,'EUR/USD',t.units,money(t.profit)]);if(!remote.history.length)row($('history'),['Sin cierres simulados.']);$('activity').replaceChildren();for(const e of remote.events){const li=document.createElement('li');li.textContent=e;$('activity').append(li);}$('example').textContent='Avanzar un paso simulado';remoteDraw();}
async function refresh(){if(busy||!endpoint)return;busy=true;try{remote=await api('state');showRemote();}catch(e){notice('Sin respuesta del motor. El estado mostrado puede estar desactualizado. '+e.message);document.querySelector('.connection').textContent='● Motor sin respuesta · OANDA desconectado';}finally{busy=false;}}
async function command(action,risk){if(busy)return notice('Esperando respuesta del servidor.');busy=true;try{remote=await api('command',{action,risk});showRemote();notice('Cambio aplicado al motor de simulación. OANDA sigue desconectado.');}catch(e){notice('No se confirmó el cambio: '+e.message);}finally{busy=false;}}
$('server-config').onsubmit=async e=>{e.preventDefault();try{const u=new URL($('server-url').value);if(u.username||u.password||u.search||u.hash||!(['https:'].includes(u.protocol)||u.protocol==='http:'&&['127.0.0.1','localhost'].includes(u.hostname)))throw Error('Usa HTTPS o un servidor local.');endpoint=u.origin;access=$('panel-token').value;remote=await api('state');$('panel-token').value='';showRemote();clearInterval(timer);timer=setInterval(refresh,3000);notice('Conectado al motor simulado. Puedes activarlo desde Panel.');}catch(e){endpoint='';access='';remote=null;notice('No se pudo conectar: '+e.message);}};
$('toggle').onclick=()=>endpoint?command(remote?.active?'pause':'start'):localToggle();
$('close').onclick=()=>endpoint?(confirm('¿Pausar entradas y cerrar todas las posiciones simuladas del servidor?')&&command('close')):localClose();
$('example').onclick=()=>endpoint?command('step'):localExample();
$('config').onsubmit=e=>{if(!endpoint)return localConfig(e);e.preventDefault();command('config',Number($('risk-input').value));};
$('reset').onclick=()=>endpoint?notice('El historial del servidor se conserva. Para reiniciar una prueba, crea una base de datos nueva con el servidor detenido.'):localReset();
$('export').onclick=()=>{if(!endpoint)return localExport();if(!remote)return;const rows=['fecha,par,unidades,resultado_simulado_usd',...remote.history.map(t=>[JSON.stringify(t.time),'EUR_USD',t.units,t.profit].join(','))];const u=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='historial-motor-simulado.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
$('disconnect').onclick=()=>{if(endpoint&&!confirm('Desconectar el panel no pausa el motor. ¿Continuar?'))return;clearInterval(timer);timer=null;endpoint='';access='';remote=null;location.reload();};
draw=remoteDraw;
